import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o,af as r}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const A=JSON.parse('{"title":"阿里故障复盘 Agent 系统","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/agent/alibaba-incident-review-agent.md","filePath":"zh/tech/agent/alibaba-incident-review-agent.md","lastUpdated":1782518791000}'),l={name:"zh/tech/agent/alibaba-incident-review-agent.md"};function n(i,t,s,g,d,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="阿里故障复盘-agent-系统" tabindex="-1">阿里故障复盘 Agent 系统 <a class="header-anchor" href="#阿里故障复盘-agent-系统" aria-label="Permalink to &quot;阿里故障复盘 Agent 系统&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://new.qq.com/rain/a/20251009A01JF900" target="_blank" rel="noreferrer">别让故障复盘流于形式：用AI挖掘每一次&quot;跌倒&quot;的价值</a> | 原始链接：<a href="https://www.bestblogs.dev/article/b68d8384" target="_blank" rel="noreferrer">https://www.bestblogs.dev/article/b68d8384</a></p></blockquote><h2 id="一、故障复盘的业务思考" tabindex="-1">一、故障复盘的业务思考 <a class="header-anchor" href="#一、故障复盘的业务思考" aria-label="Permalink to &quot;一、故障复盘的业务思考&quot;">​</a></h2><p>技术支持工作的本质目标是帮助业务方做好稳定性，提升 C 端用户体验，主张 <strong>blameless（无责）</strong> 的复盘文化。</p><p>复盘的核心价值在于：</p><ul><li><strong>准确深度发现</strong>当前系统的风险，并推动闭环解决</li><li><strong>举一反三</strong>：将未发生故障但存在同样风险的系统也实现真正规避</li><li><strong>数据资产沉淀</strong>：复盘结果作为稳定性工作的方向输入，经验不足的研发可从历史故障中学习故障树 FTA 路径、恢复手段和关键决策</li></ul><h3 id="复盘实操难点" tabindex="-1">复盘实操难点 <a class="header-anchor" href="#复盘实操难点" aria-label="Permalink to &quot;复盘实操难点&quot;">​</a></h3><ol><li>变更操作导致的故障，当事人不太愿意深度编写原因</li><li>链路长的故障，各层都不愿串联整个过程</li><li>人性因素：故障恢复后报告从简，深入讨论要&quot;写出来不是我的问题&quot;</li><li>技术支持对技术理解力和稳定性领域知识不足，难以提出架构层面的关注点</li><li>开发认为技术支持不懂技术，即便提出真问题也不愿深入沟通</li></ol><h3 id="ai-赋能思路" tabindex="-1">AI 赋能思路 <a class="header-anchor" href="#ai-赋能思路" aria-label="Permalink to &quot;AI 赋能思路&quot;">​</a></h3><p>借助 AI 的<strong>识别与生成</strong>和<strong>推理与规划</strong>能力解决复盘的专业性和深度问题，提供以下核心能力：</p><ol><li><strong>生成故障概述、时间线、影响面</strong>：连接监控和变更系统，提升事中信息协同效率</li><li><strong>故障原因理解 → 生成故障树分析 FTA</strong>：生成更专业和深度的关注点</li><li><strong>故障多维度标签化 + 复盘数据结构化</strong>：形成有效的数据资产</li><li><strong>识别风险 → 系统健康中心</strong>：可视化产品线/业务线的系统健康度</li><li><strong>故障问答</strong>：自然语言交互搜索、统计、分析故障相关信息</li><li><strong>深挖共性风险</strong>：AI 的强项</li></ol><h2 id="二、智能复盘-agent-整体介绍" tabindex="-1">二、智能复盘 Agent 整体介绍 <a class="header-anchor" href="#二、智能复盘-agent-整体介绍" aria-label="Permalink to &quot;二、智能复盘 Agent 整体介绍&quot;">​</a></h2><h3 id="目标用户" tabindex="-1">目标用户 <a class="header-anchor" href="#目标用户" aria-label="Permalink to &quot;目标用户&quot;">​</a></h3><ul><li>SRE 团队</li><li>DevOps 工程师</li><li>技术支持</li><li>业务稳定性负责人</li></ul><blockquote><p>AI 工具不是要替代工程师，而是要<strong>放大工程师的智慧</strong>。</p></blockquote><h3 id="核心价值" tabindex="-1">核心价值 <a class="header-anchor" href="#核心价值" aria-label="Permalink to &quot;核心价值&quot;">​</a></h3><p>将传统的&quot;人工填空题&quot;转变为&quot;AI 辅助的深度分析&quot;。</p><h3 id="智能复盘功能全景" tabindex="-1">智能复盘功能全景 <a class="header-anchor" href="#智能复盘功能全景" aria-label="Permalink to &quot;智能复盘功能全景&quot;">​</a></h3><ul><li><strong>全景数据聚合</strong>：自动从应急群聊（钉钉等）、在线会议、应急平台拉取所有相关信息</li><li><strong>一键智能生成</strong>：故障恢复后自动/手动触发，生成覆盖&quot;故障概述、时间线、影响面&quot;的报告初稿</li><li><strong>对话式深度挖掘</strong>：用户可追问，故障原因 Agent、关注点 Agent、改进措施 Agent 协同分析</li><li><strong>情景化知识增强</strong>：结合模型上下文与内部知识（领域术语库、历史复盘文档知识库）</li><li><strong>闭环式资产沉淀</strong>：报告归档后作为结构化知识沉淀到知识库</li></ul><h2 id="三、核心技术架构" tabindex="-1">三、核心技术架构 <a class="header-anchor" href="#三、核心技术架构" aria-label="Permalink to &quot;三、核心技术架构&quot;">​</a></h2><h3 id="_3-1-multi-agent-协作架构" tabindex="-1">3.1 Multi-Agent 协作架构 <a class="header-anchor" href="#_3-1-multi-agent-协作架构" aria-label="Permalink to &quot;3.1 Multi-Agent 协作架构&quot;">​</a></h3><p>以&quot;故障复盘 Multi-Agent&quot;为核心，通过多个角色型 Agent 协作完成复盘任务的编排、意图识别与执行。</p><p>核心组件：</p><ul><li><strong>Plan Agent</strong>：解析用户意图，决策是 Ask 任务还是专业 Agent 任务</li><li><strong>Task Expert（任务专家 Agent）</strong>：被委派执行深度挖掘，自主多轮与底层服务交互</li><li><strong>Report-Composer</strong>：收集所有碎片化结论和证据，整合成逻辑清晰、有理有据的回答</li></ul><h3 id="_3-2-复盘时序流程" tabindex="-1">3.2 复盘时序流程 <a class="header-anchor" href="#_3-2-复盘时序流程" aria-label="Permalink to &quot;3.2 复盘时序流程&quot;">​</a></h3><ol><li><strong>提问与规划</strong>：用户通过 Web UI 提问，Plan Agent 解析意图</li><li><strong>编排与委派</strong>：将每个子任务精准委派给相应能力的 Task Expert</li><li><strong>专家执行与深度交互</strong>：调用外部 API 获取实时数据，查询 RAG 知识库，请求大模型进行复杂逻辑推理</li><li><strong>整合与响应</strong>：Report-Composer 模块整合所有结论，最终呈现给用户</li></ol><h2 id="四、核心技术实现" tabindex="-1">四、核心技术实现 <a class="header-anchor" href="#四、核心技术实现" aria-label="Permalink to &quot;四、核心技术实现&quot;">​</a></h2><h3 id="_4-1-数据采集与预处理" tabindex="-1">4.1 数据采集与预处理 <a class="header-anchor" href="#_4-1-数据采集与预处理" aria-label="Permalink to &quot;4.1 数据采集与预处理&quot;">​</a></h3><p><strong>挑战</strong>：多源异构数据存在格式不统一、表达方式多样、信息密度不均等问题。</p><p><strong>目标</strong>：构建统一的故障数据层，赋能高效、精准的根因分析（RCA）。通过智能降噪、语音校准、多模态信息融合等预处理流程，将原始数据转化为包含&quot;Who, When, Where, What&quot;等要素的<strong>结构化统一事件流</strong>。</p><h3 id="_4-2-memory-管理机制" tabindex="-1">4.2 Memory 管理机制 <a class="header-anchor" href="#_4-2-memory-管理机制" aria-label="Permalink to &quot;4.2 Memory 管理机制&quot;">​</a></h3><p>对于 LLM 来说，记忆不是越多越好，而是要<strong>记得住关键，忘得掉干扰</strong>。</p><p>在多轮、长流程的故障复盘任务中，Agent 的上下文会迅速膨胀，可能导致 Token 溢出、关键信息被淹没、推理链断裂。</p><h4 id="通用-agent-vs-智能复盘-agent-的-memory-差异" tabindex="-1">通用 Agent vs 智能复盘 Agent 的 Memory 差异 <a class="header-anchor" href="#通用-agent-vs-智能复盘-agent-的-memory-差异" aria-label="Permalink to &quot;通用 Agent vs 智能复盘 Agent 的 Memory 差异&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>通用 Agent</th><th>智能复盘 Agent</th></tr></thead><tbody><tr><td>任务性质</td><td>单流程、单目标、交互独立</td><td>长流程、多阶段、强依赖历史抉择</td></tr><tr><td>上下文来源</td><td>用户输入+少量工具调用</td><td>多轮对话+应急系统日志+会议记录+多次工具调用</td></tr><tr><td>信息体量</td><td>百~千 Token 级</td><td>动辄数万 Token</td></tr><tr><td>记忆粒度</td><td>关键意图/实体提取</td><td>需保留事件时序、因果链、责任归属等结构化线索</td></tr><tr><td>噪音比例</td><td>相对较低</td><td>极高（会议记录中大量口语化、重复、无关讨论）</td></tr></tbody></table><h4 id="memory-管理三步法" tabindex="-1">Memory 管理三步法 <a class="header-anchor" href="#memory-管理三步法" aria-label="Permalink to &quot;Memory 管理三步法&quot;">​</a></h4><ol><li><strong>去噪</strong>：预处理阶段剔除冗余和噪声数据</li><li><strong>Summary（提要）</strong>：采用 ConversationBufferSummary 方式，当 Token 超过阈值，调用专门 LLM 将冗长对话历史提炼成结构化摘要，完整保留最近 N 条上下文和 System Prompt</li><li><strong>保鲜</strong>：重要指令（System 消息、用户核心需求）重新注入模型记忆范围，防止被&quot;遗忘&quot;</li></ol><p><strong>8 段式 Summary 结构</strong>（模拟 SRE 复盘思维）：</p><ol><li>Primary Request and Intent（主要请求和意图）</li><li>Key Technical Concepts（关键技术概念）</li><li>Files and Code Sections（文件和代码片段）</li><li>Errors and Fixes（错误和修复）</li><li>Problem Solving（问题解决过程）</li><li>All User Messages（所有用户消息）</li><li>Pending Tasks（待处理任务）</li><li>Current Work（当前工作状态）</li></ol><h3 id="_4-3-意图识别-通用-agent-→-多-agent-分流与嵌套" tabindex="-1">4.3 意图识别：通用 Agent → 多 Agent 分流与嵌套 <a class="header-anchor" href="#_4-3-意图识别-通用-agent-→-多-agent-分流与嵌套" aria-label="Permalink to &quot;4.3 意图识别：通用 Agent → 多 Agent 分流与嵌套&quot;">​</a></h3><h4 id="通用-agent-的问题" tabindex="-1">通用 Agent 的问题 <a class="header-anchor" href="#通用-agent-的问题" aria-label="Permalink to &quot;通用 Agent 的问题&quot;">​</a></h4><ul><li>工具混杂与提示词膨胀</li><li>交互风格难以兼顾（口语化交流 vs 专业化内容生产）</li><li>可维护性与可观测性差</li><li>成本与稳定性矛盾</li></ul><h4 id="多-agent-体系设计" tabindex="-1">多 Agent 体系设计 <a class="header-anchor" href="#多-agent-体系设计" aria-label="Permalink to &quot;多 Agent 体系设计&quot;">​</a></h4><ul><li><strong>入口分流</strong>：Chat 模式 vs Work 模式，通过少样本意图识别自动路由</li><li><strong>ChatAgent</strong>：聚焦沟通与轻量分析，口语化系统提示词</li><li><strong>WorkAgent</strong>：聚焦任务执行与专业化产出，面向复盘的分析和数据聚合工具</li><li><strong>Agent 嵌套</strong>：将同一领域的工具与上下文聚合为独立&quot;业务 Agent&quot;，通过 selectAgent 在外层统一包装</li></ul><h3 id="_4-4-agent-动态页面交互界面" tabindex="-1">4.4 Agent 动态页面交互界面 <a class="header-anchor" href="#_4-4-agent-动态页面交互界面" aria-label="Permalink to &quot;4.4 Agent 动态页面交互界面&quot;">​</a></h3><h4 id="通用-agent-交互问题" tabindex="-1">通用 Agent 交互问题 <a class="header-anchor" href="#通用-agent-交互问题" aria-label="Permalink to &quot;通用 Agent 交互问题&quot;">​</a></h4><ul><li>输出形态：整个推理过程折叠为单次或少量文本消息流，过程不可见</li><li>会话管理：以内存或简单持久化为主，消息生产和消费耦合</li><li>UI 交互：纯文本为主，缺乏对前端组件的原生支持</li></ul><h4 id="智能复盘-agent-的三大交互能力" tabindex="-1">智能复盘 Agent 的三大交互能力 <a class="header-anchor" href="#智能复盘-agent-的三大交互能力" aria-label="Permalink to &quot;智能复盘 Agent 的三大交互能力&quot;">​</a></h4><ol><li><strong>流式交互的 Step 级执行与曝光控制</strong>：每个 step 完成后以流方式返回前端，通过显式可见性控制区分&quot;可透出内容&quot;和&quot;内部隐私内容&quot;</li><li><strong>基于缓存的会话管理（生产者/消费者模式）</strong>：Agent 执行过程中将消息追加式写入缓存，前端聊天渲染侧按需读取并全量渲染，实现时序一致性、曝光粒度可控、异步与弹性</li><li><strong>灵活 UI 交互（前端组件封装为 Tool）</strong>：将预开发的前端组件以&quot;工具&quot;形式注册给模型使用，识别&quot;组件 JSON&quot;后动态渲染卡片、表格、图表、表单、流程确认等高级交互</li></ol><h3 id="_4-5-rag-知识增强" tabindex="-1">4.5 RAG 知识增强 <a class="header-anchor" href="#_4-5-rag-知识增强" aria-label="Permalink to &quot;4.5 RAG 知识增强&quot;">​</a></h3><p>在阿里巴巴大量私域知识环境下，RAG 至关重要：</p><ul><li><strong>私域知识缺失</strong>：企业特有的技术架构、业务流程、专有名词等信息不在通用大模型训练数据中</li><li><strong>生成内容幻觉</strong>：缺乏准确知识支撑，模型可能产生与事实不符的臆测内容</li></ul><p><strong>知识增强闭环</strong>：知识发现 → 沉淀至专属知识库 → 通过 RAG 检索精准上下文 → 应用于后续复盘</p><h3 id="_4-6-评测机制" tabindex="-1">4.6 评测机制 <a class="header-anchor" href="#_4-6-评测机制" aria-label="Permalink to &quot;4.6 评测机制&quot;">​</a></h3><h4 id="智能复盘-agent-vs-通用-agent-评测差异" tabindex="-1">智能复盘 Agent vs 通用 Agent 评测差异 <a class="header-anchor" href="#智能复盘-agent-vs-通用-agent-评测差异" aria-label="Permalink to &quot;智能复盘 Agent vs 通用 Agent 评测差异&quot;">​</a></h4><table tabindex="0"><thead><tr><th>维度</th><th>通用 Agent</th><th>智能复盘 Agent</th></tr></thead><tbody><tr><td>评估重点</td><td>答案正确性、响应速度</td><td>洞察深度、逻辑完整性、改进建议可执行性</td></tr><tr><td>输出形式</td><td>单轮、短文本</td><td>多模块长文档（时间线、根因、关注点等）</td></tr><tr><td>标准答案</td><td>明确（如 FAQ 库）</td><td>多解、开放</td></tr><tr><td>价值判断</td><td>是否&quot;答对了&quot;</td><td>是否&quot;挖的深&quot;&quot;提的准&quot;&quot;改得动&quot;</td></tr></tbody></table><h4 id="评测体系演进" tabindex="-1">评测体系演进 <a class="header-anchor" href="#评测体系演进" aria-label="Permalink to &quot;评测体系演进&quot;">​</a></h4><table tabindex="0"><thead><tr><th>阶段</th><th>方法</th><th>问题</th></tr></thead><tbody><tr><td>第一阶段</td><td>ROUGE/BLEU（词汇重合度）</td><td>AI 靠堆砌常用词汇&quot;得高分&quot;，但关注点采纳率不高</td></tr><tr><td>第二阶段</td><td>BERTScore（向量语义相似）</td><td>评分普遍较高，无法区分&quot;表面相关&quot;与&quot;深度匹配&quot;</td></tr><tr><td>第三阶段</td><td>LLM-as-Judge（让大模型做裁判）</td><td>对&quot;编造但听起来合理&quot;的内容打分高</td></tr><tr><td>第四阶段</td><td><strong>业务价值导向打分</strong></td><td>结合&quot;标准答案关注点&quot;+&quot;AI 生成关注点&quot;+&quot;复盘文档原文&quot;，从洞察深度、逻辑完整性、可执行性、证据支撑四个维度打分</td></tr></tbody></table><h3 id="_4-7-提示词调优历程" tabindex="-1">4.7 提示词调优历程 <a class="header-anchor" href="#_4-7-提示词调优历程" aria-label="Permalink to &quot;4.7 提示词调优历程&quot;">​</a></h3><h4 id="v1-泛化生成-期望-ai-靠-常识-输出价值" tabindex="-1">V1 - 泛化生成（期望 AI 靠&quot;常识&quot;输出价值） <a class="header-anchor" href="#v1-泛化生成-期望-ai-靠-常识-输出价值" aria-label="Permalink to &quot;V1 - 泛化生成（期望 AI 靠&quot;常识&quot;输出价值）&quot;">​</a></h4><p>让大模型理解故障背景后自动生成关注点。<strong>问题</strong>：Prompt 没有约束，AI 自由发挥，靠&quot;常识&quot;拼凑答案，关注点描述太泛。</p><h4 id="v2-增加聚焦风险标签" tabindex="-1">V2 - 增加聚焦风险标签 <a class="header-anchor" href="#v2-增加聚焦风险标签" aria-label="Permalink to &quot;V2 - 增加聚焦风险标签&quot;">​</a></h4><p>引入风险标签库（容灾架构、高可用、可扩展性等），用规则&quot;框住&quot;AI。<strong>问题</strong>：大模型生搬硬套，没有架构问题也要吹毛求疵；忽略实际系统情况，强调时间上的不合理。</p><h4 id="v3-工程化尝试-仍未跳出标签陷阱" tabindex="-1">V3 - 工程化尝试（仍未跳出标签陷阱） <a class="header-anchor" href="#v3-工程化尝试-仍未跳出标签陷阱" aria-label="Permalink to &quot;V3 - 工程化尝试（仍未跳出标签陷阱）&quot;">​</a></h4><p>将标签库领域拆分为 5 个独立子集，并行调用各模型实例专注特定领域。<strong>问题</strong>：标签无法完全穷举，更新维护成本高；存在强行匹配现象。</p><h4 id="v4-摒弃风险标签-回归问题本质" tabindex="-1">V4 - 摒弃风险标签，回归问题本质 <a class="header-anchor" href="#v4-摒弃风险标签-回归问题本质" aria-label="Permalink to &quot;V4 - 摒弃风险标签，回归问题本质&quot;">​</a></h4><p>核心优化：</p><ul><li><strong>两阶段拆解</strong>：第一阶段 AI 从多维度提出具体问题（包含服务名、接口、配置项等实体），第二阶段严格基于文档分析原因和改进</li><li><strong>摒弃标签库</strong>：将分类动作后置，让 AI 自由聚焦真实问题</li><li><strong>鼓励上下文引用</strong>：要求问题包含具体实体，分析引用日志、配置、调用链等证据</li><li><strong>防幻觉机制</strong>：若信息不足，【问题分析】和【改进措施】直接置空，<strong>宁可不说，不可乱说</strong></li></ul><h2 id="五、实战案例-agent-赋能各角色" tabindex="-1">五、实战案例：Agent 赋能各角色 <a class="header-anchor" href="#五、实战案例-agent-赋能各角色" aria-label="Permalink to &quot;五、实战案例：Agent 赋能各角色&quot;">​</a></h2><h3 id="_5-1-技术支持视角" tabindex="-1">5.1 技术支持视角 <a class="header-anchor" href="#_5-1-技术支持视角" aria-label="Permalink to &quot;5.1 技术支持视角&quot;">​</a></h3><ul><li>故障结束实时获取报告初版（P4/P5 可在 2~3 天 → <strong>1 天内</strong>完成）</li><li>通过 Agent 生成故障关注点和改进措施，<strong>关注点采纳率 60%+</strong></li><li>从&quot;信息整合者&quot;升级为&quot;风险挖掘者&quot;</li></ul><h3 id="_5-2-研发视角" tabindex="-1">5.2 研发视角 <a class="header-anchor" href="#_5-2-研发视角" aria-label="Permalink to &quot;5.2 研发视角&quot;">​</a></h3><ul><li>Agent 自动生成初版复盘文档作为事实依据库，避免&quot;凭记忆写复盘&quot;</li><li>通过 Agent 进行故障原因质量分析，自动识别缺失维度并给出补全建议</li><li>发现分析盲区，提升故障原因质量下限</li></ul><h3 id="_5-3-普通用户视角" tabindex="-1">5.3 普通用户视角 <a class="header-anchor" href="#_5-3-普通用户视角" aria-label="Permalink to &quot;5.3 普通用户视角&quot;">​</a></h3><ul><li>Agent 自动提取<strong>简洁、可读性强的故障摘要</strong>，10 秒内掌握全局</li><li>生成<strong>可视化故障链路时序图</strong></li><li>提供<strong>可视化故障树（FTA 图）</strong>，以自顶向下方式展示根因链</li></ul><h2 id="六、核心要点总结" tabindex="-1">六、核心要点总结 <a class="header-anchor" href="#六、核心要点总结" aria-label="Permalink to &quot;六、核心要点总结&quot;">​</a></h2><ol><li><strong>Blameless 文化</strong>：故障不是一个&quot;如果&quot;的问题，而是一个&quot;何时&quot;的问题，拥抱风险，理性客观解除风险</li><li><strong>Multi-Agent 架构</strong>：通过 Plan Agent + Task Expert + Report-Composer 协作，实现深度分析与结构化输出</li><li><strong>Memory 管理三步法</strong>：去噪 → Summary 提要 → 保鲜，确保 Agent 在复杂任务中&quot;不迷路、不遗忘、不超载&quot;</li><li><strong>意图识别分流</strong>：Chat 模式处理沟通答疑，Work 模式处理专业化任务执行</li><li><strong>提示词演进</strong>：从泛化生成 → 标签约束 → 两阶段拆解，本质是从&quot;教 AI 该说什么&quot;到&quot;让 AI 真理解问题&quot;</li><li><strong>评测方法</strong>：无银弹，需结合相似性指标（监控退化）+ 业务价值导向打分（衡量优化效果）</li></ol>',77)])])}const m=a(l,[["render",n]]);export{A as __pageData,m as default};
